// Configure the Gate reachable from your n8n runtime and the browser review URL.
const gateBaseUrl = 'http://127.0.0.1:3100/api';
const reviewBaseUrl = 'http://127.0.0.1:3100';

// Reuse each source key when replaying the same document and extracted payload.
// Editing a reviewed document uses the review interface and its revision check.
const invoices = [
  {
    "intakeKey": "n8n-demo-invoice-42",
    "extracted": {
      "invoiceNumber": "DEMO-42",
      "supplier": "Synthetic Paper Co.",
      "currency": "USD",
      "amountMinor": 12850
    }
  },
  {
    "intakeKey": "n8n-demo-invoice-43",
    "extracted": {
      "invoiceNumber": "DEMO-43",
      "supplier": "Synthetic Hosting Co.",
      "currency": "USD",
      "amountMinor": 67000
    }
  }
];
return invoices.map(invoice => ({ json: {
  gateBaseUrl: gateBaseUrl.replace(/\/$/, ''),
  reviewBaseUrl: reviewBaseUrl.replace(/\/$/, ''),
  ...invoice,
} }));

const source = $('Synthetic invoices').item.json;
const document = $json.document;
return { json: {
  documentId: document.id,
  intakeKey: document.intakeKey,
  invoiceNumber: document.extracted.invoiceNumber,
  status: document.status,
  revision: document.revision,
  amountMinor: document.extracted.amountMinor,
  currency: document.extracted.currency,
  reviewUrl: source.reviewBaseUrl + '/?documentId=' + encodeURIComponent(document.id),
} };
